// C++ port of ClassExtensions.pas (interface section).
// Generated by tools/pas2h.py, then maintained by hand.
//
// The Delphi unit changed the class of existing controls at runtime
// (NewWinControlType, "dangerous magic") to add drop target support,
// special list view hints and pick list cell editors.  A C++ object cannot
// change its class, so the port attaches the additional behaviour to the
// existing widget instance (event filters / item delegate owned by the
// widget).  The extension classes below therefore have no data members and
// no virtual overrides: all their methods only use the public interface of
// the base class, so a widget created by uic (QTreeWidget, TListView,
// QListWidget, QTableWidget) may be used through them exactly like in
// Delphi:
//
//   ui.ListView = static_cast<TListView*>(NewWinControlType(ui.ListView,
//                     WinControlClass<TListViewAcceptingFilesAndSpecialHint>(), ctcmDangerousMagic));
//   static_cast<TListViewAcceptingFilesAndSpecialHint*>(ui.ListView)->ActivateAcceptFiles();
//   static_cast<TListViewAcceptingFilesAndSpecialHint*>(ui.ListView)->SetOnDragDrop(
//       [this](QObject *S, QObject *Src, int X, int Y) { MainDragDrop(S, Src, X, Y); });
//
// NewWinControlType always returns OldControl (signal connections and the
// ui pointer stay valid).  Dropped files are passed to the OnDragDrop handler
// as Source object that is a TStringList (like in Delphi):
//   TStringList *St = dynamic_cast<TStringList*>(Source); if (St == nullptr) return;
#pragma once

#include "DelphiCompat.h"
#include "Graphics.h"
#include "ComCtrls.h"
#include <QtWidgets>
#include <QtXml>
#include <QtNetwork>
#include <functional>

// OnDragDrop(Sender, Source, X, Y)
using TDragDropEvent = std::function<void(QObject*, QObject*, int, int)>;

// Source object of a file drop (WM_DROPFILES): the list of dropped files.
class TDropFilesSource : public QObject, public TStringList
{
public:
    TDropFilesSource() = default;
    ~TDropFilesSource() override = default;
};

class TTreeViewAcceptingFiles : public QTreeWidget
{
public:
    using QTreeWidget::QTreeWidget;
    void ActivateAcceptFiles();
    // OnDragDrop is called for dropped files (X,Y = drop position in the viewport)
    TDragDropEvent OnDragDrop() const;
    void SetOnDragDrop(TDragDropEvent Value);
};
class TListViewAcceptingFiles : public TListView
{
public:
    using TListView::TListView;
    void ActivateAcceptFiles();
    // OnDragDrop is called for dropped files (X,Y = -1)
    TDragDropEvent OnDragDrop() const;
    void SetOnDragDrop(TDragDropEvent Value);
};
// Hints with the text of OnInfoTip, shown at the mouse position for a long time
class TListViewSpecialHint : public TListView
{
public:
    using TListView::TListView;
    void ActivateSpecialHint();   // done by NewWinControlType
};
class TListViewAcceptingFilesAndSpecialHint : public TListViewAcceptingFiles
{
public:
    using TListViewAcceptingFiles::TListViewAcceptingFiles;
    void ActivateSpecialHint();   // done by NewWinControlType
};
using TListForCellEvent = std::function<void(int, int, bool&)>;
using TGetListForCellEvent = std::function<void(int, int, TStringList*)>;
// String grid with pick list cell editors (ACol/ARow in VCL coordinates,
// i.e. including the fixed rows/columns, see vclFixedRows/vclFixedCols)
class TStringGridEx : public QTableWidget
{
public:
    using QTableWidget::QTableWidget;
    // properties
    TListForCellEvent OnListForCell() const;
    void SetOnListForCell(TListForCellEvent Value);
    TGetListForCellEvent OnGetListForCell() const;
    void SetOnGetListForCell(TGetListForCellEvent Value);
    void ActivatePickListEditor();   // CreateEditor override, done by NewWinControlType
};
class TListBoxAcceptingFiles : public QListWidget
{
public:
    using QListWidget::QListWidget;
    void ActivateAcceptFiles();
    // OnDragDrop is called for dropped files (X,Y = drop position in the viewport)
    TDragDropEvent OnDragDrop() const;
    void SetOnDragDrop(TDragDropEvent Value);
};
using TWinControlClass = std::function<QWidget*(QWidget*)>;  // Delphi metaclass: class of TWinControl
// TWinControlClass value of class T (Delphi: passing the class name as metaclass)
template <class T> TWinControlClass WinControlClass() { return [](QWidget* AOwner) -> QWidget* { return new T(AOwner); }; }
enum TWinControlTypeChangeMethod { ctcmDangerousMagic, ctcmStoreAndRestore, ctcmCopyProperties };
QWidget* NewWinControlType(QWidget* OldControl, TWinControlClass NewControlClass, TWinControlTypeChangeMethod ChangeMethod);
